// Color Waves - color only, ANIMATED. Runs INSIDE shadeSurface().
// Three point sources wander slowly through space, each sending out spherical
// ripples; where the ripples meet they interfere. The wave height picks between
// the dock colors and drives a rainbow that drifts with time; the crests glow.
// Measured in 3D, so there are no seams on any surface.
// No displacement: one evaluation per pixel, cheap at any resolution.
// In scope: pModel, t. Dock colors: u_col1 = crests, u_col2 = troughs.

float FREQ    = 14.0 * max(E, 0.05);   // slider E   // ripples per unit      [4 .. 40]
float SPEED   = 2.0 * F;               // slider F   // wave speed            [0 .. 6]
float RAINBOW = 0.55;   // 0 = dock colors only, 1 = full spectrum              [0 .. 1]
float GLOW    = 0.35;   // brightness of the crests                             [0 .. 1]

vec3 s1 = 0.9 * vec3(sin(0.31 * t),       cos(0.23 * t),       sin(0.17 * t + 1.0));
vec3 s2 = 0.9 * vec3(cos(0.27 * t + 2.0), sin(0.19 * t + 0.5), cos(0.29 * t));
vec3 s3 = 0.9 * vec3(sin(0.21 * t + 4.0), sin(0.33 * t + 3.0), cos(0.15 * t + 2.0));

float w = sin(FREQ * length(pModel - s1) - SPEED * t)
        + sin(FREQ * length(pModel - s2) - SPEED * t * 1.13)
        + sin(FREQ * length(pModel - s3) - SPEED * t * 0.87);
w /= 3.0;   // [-1, 1]

vec3 dock    = mix(ubuf.u_col2, ubuf.u_col1, 0.5 + 0.5 * w);
vec3 rainbow = 0.5 + 0.5 * cos(6.2832 * (0.35 * w + 0.04 * t + vec3(0.0, 0.33, 0.67)));
vec3 col = mix(dock, rainbow * (0.4 + 0.6 * dock), RAINBOW);
col += GLOW * smoothstep(0.55, 0.95, w) * vec3(1.0);

textureCol = col;
